const dir=new URL('./',import.meta.url),shared=new URL('../',import.meta.url),hash=b=>createHash('sha256').update(b).digest('hex');
export const DISPEL_PARTY_INPUTS={
 partyStatusBytes:{dtype:'float32',width:16,default:Array(16).fill(0),domain:{min:0,max:255,integer:true},label:'味方4人の状態word14（各little-endian4byte）'},
 partyFlagBytes:{dtype:'float32',width:16,default:Array(16).fill(0),domain:{min:0,max:255,integer:true},label:'味方4人のflags18（各little-endian4byte）'},
 partyRankFields:{dtype:'float32',width:40,default:Array(40).fill(0),domain:{min:-4,max:3,integer:true},label:'味方4人のrank word58（各signed3-bit×10、元順）'}
};
function finish(g){g.contract.inputDomains=Object.fromEntries(g.inputs.filter(d=>g.contract.inputDomains[d.name]||d.dtype==='bool').map(d=>[d.name,{...(g.contract.inputDomains[d.name]??{values:[false,true,0,1]}),width:d.shape[1]}]));g.contract.inputContractVersion=1;return g;}
const load=async(name,base=dir)=>JSON.parse(await readFile(new URL(`${name}.json`,base)));
const bit=(g,bytes,n)=>{const q=g.floor(g.mul(bytes[n>>>3],2**-(n&7)));return g.gt(g.sub(q,g.mul(g.floor(g.mul(q,.5)),2)),0);};
const selectBool=(g,c,a,b)=>g.gt(g.where(c,g.cast(a,'float32'),g.cast(b,'float32')),0);
export function dispelTarget(g,x,base){
 const selected=g.eq(x.selectorIndex,106),active=g.and(x.enabled,selected),old=g.inline(base,{...x,enabled:g.and(x.enabled,g.not(selected))},`dispel_previous_${g.index}`),
 ids=g.split(x.ids,4),present=g.split(x.present,4),candidate=g.split(x.candidate,4),status=g.split(x.partyStatusBytes,16),flags=g.split(x.partyFlagBytes,16),ranks=g.split(x.partyRankFields,40),
 eligible=ids.map((_,i)=>g.and(present[i],candidate[i],g.not(bit(g,status.slice(i*4,i*4+4),0)),g.not(bit(g,flags.slice(i*4,i*4+4),13)))),
 statusBits=[23,24,9,27,28,29,20,22,26,30,21,31],flagBits=[7,3,1,2,9,10,8],positiveRanks=new Set([0,1,2,4,6]),
 affected=eligible.map((e,i)=>g.and(e,g.or(...statusBits.map(b=>bit(g,status.slice(i*4,i*4+4),b)),...flagBits.map(b=>bit(g,flags.slice(i*4,i*4+4),b)),...ranks.slice(i*10,i*10+10).map((rank,j)=>positiveRanks.has(j)?g.gt(rank,0):g.not(g.eq(rank,0)))))),
 count=eligible.reduce((n,e)=>g.add(n,g.cast(e,'float32')),g.constant(0)),affectable=affected.reduce((n,e)=>g.add(n,g.cast(e,'float32')),g.constant(0)),accepted=g.and(active,g.gt(affectable,0));
 const packed=Array(4).fill(g.constant(0));let rank=g.constant(0);for(let i=0;i<4;i++){for(let j=0;j<4;j++)packed[j]=g.where(g.and(eligible[i],g.eq(rank,j)),ids[i],packed[j]);rank=g.add(rank,g.cast(eligible[i],'float32'));}
 const buffer=g.cat([...packed,...g.split(x.previousTargets,8).slice(4)]),newCount=g.where(active,g.where(g.gt(count,0),g.where(accepted,count,0),x.previousTargetCount),x.previousTargetCount);
 return{nextSeed:g.where(selected,x.seed,old.nextSeed),nextPosition:g.where(selected,x.position,old.nextPosition),consumed:g.where(selected,g.constant(0,'int32'),old.consumed),supported:selectBool(g,selected,g.eq(0,0),old.supported),callbackSuccess:selectBool(g,selected,accepted,old.callbackSuccess),targetCount:g.where(selected,newCount,old.targetCount),targets:g.where(selected,g.where(accepted,buffer,x.previousTargets),old.targets),filteredCount:g.where(selected,count,old.filteredCount),rageCandidateUsed:g.where(selected,g.constant(0,'int32'),old.rageCandidateUsed),partyCount:g.where(selected,count,old.partyCount),affectableCount:g.where(selected,affectable,old.affectableCount)};
}
export async function buildDispelTargetGraph(){const previous=await load('rom-ai-default-repeat-target4'),file='src/Combat/Overlay_24/func_ov024_021f3e64.cpp';
 const g=new Graph('rom-ai-dispel-target4',{...structuredClone(previous.contract),authority:[...previous.contract.authority,{file,sha256:sourceSHA256(file),address:'JPN overlay24:0x021f4630',actualQuery:'evidence-v2/ghidra/repeat-dispel-target-defined/response.json'}],
 scope:'Immutable previous default/common target handlers plus actual wise callback106. Enumerate eligible party, detect the exact status/flag/rank union, and accept the entire enumerated party if any target has a matching effect. All8 caller target shorts and empty/nonempty rejection write differences are preserved. No RNG in106.',
 scopeJa:'いてつくはどうの賢い対象判定を追加します。ROMの状態bit・10種類の段階補正を検査し、該当者が1人いれば列挙した味方全員を採用します。対象が空の場合と効果対象が無い場合の書込み差も保存します。',
 exactPredicate:{statusBits:[23,24,9,27,28,29,20,22,26,30,21,31],flagBits:[7,3,1,2,9,10,8],rankFieldsPositive:[0,1,2,4,6],rankFieldsNonzero:[3,5,7,8,9]},
 rawState:'For106 only, partyStatusBytes/partyFlagBytes/partyRankFields are authoritative initial raw state; dead/excluded and buff predicates are decoded inside ONNX. Other callbacks keep the existing typed projections. A full state adapter must derive both projections from the same actor memory. HP does not replace deadbit. No raw u32 is lossy-cast to a single float.',
 padding:'Callback106 returns false without count/buffer writes when no eligible candidate exists. For nonempty candidates it first sets count0; failure retains all8 caller shorts. Success copies4 local shorts (unused tails0), preserves last4, and count=eligible count. Existing callbacks retain prior contracts.',
 defaults:{...previous.contract.defaults,selectorIndex:106,...Object.fromEntries(Object.entries(DISPEL_PARTY_INPUTS).map(([k,v])=>[k,v.default]))},
 labels:{...previous.contract.labels,...Object.fromEntries(Object.entries(DISPEL_PARTY_INPUTS).map(([k,v])=>[k,v.label]))},inputDomains:{...previous.contract.inputDomains,...Object.fromEntries(Object.entries(DISPEL_PARTY_INPUTS).map(([k,v])=>[k,v.domain]))},sharedBase:{name:previous.name,sha256:hash(await readFile(new URL(`${previous.name}.onnx`,dir)))} });
 const x=Object.fromEntries(previous.inputs.map(d=>[d.name,g.input(d.name,d.shape,d.dtype)]));for(const[name,s]of Object.entries(DISPEL_PARTY_INPUTS))x[name]=g.input(name,['N',s.width],s.dtype);for(const[name,v]of Object.entries(dispelTarget(g,x,previous)))g.output(v,name);return finish(g);}
export async function buildDispelStepGraph(target){const previous=await load('rom-ai-default-repeat-step'),prefix=await load('rom-weighted-ai6',shared),decision=buildDecisionGraph(prefix);target??=await buildDispelTargetGraph();
 const g=new Graph('rom-ai-dispel-step',{...structuredClone(previous.contract),authority:[...decision.contract.authority,...target.contract.authority],scope:'One bounded candidate/gate/target step using the unchanged ROM candidate rules plus default/common/106 target handlers. Operation34 table switching is provided by a separate dynamic-definition wrapper.',scopeJa:'共通AIの候補選択・使用条件・対象決定に、いてつくはどうの対象判定を加えて1回進めます。',callbacks:target.contract.scope,rawState:target.contract.rawState,targetBufferScope:target.contract.padding,defaults:{...previous.contract.defaults,...Object.fromEntries(Object.entries(DISPEL_PARTY_INPUTS).map(([k,v])=>[k,v.default]))},labels:{...previous.contract.labels,...target.contract.labels},inputDomains:{...previous.contract.inputDomains,...target.contract.inputDomains},sharedBase:{name:previous.name,sha256:hash(await readFile(new URL(`${previous.name}.onnx`,dir)))}});
 const x=Object.fromEntries(previous.inputs.map(d=>[d.name,g.input(d.name,d.shape,d.dtype)]));for(const[name,s]of Object.entries(DISPEL_PARTY_INPUTS))x[name]=g.input(name,['N',s.width],s.dtype);for(const[name,v]of Object.entries(aiClosedStep(g,x,decision,target)))g.output(v,name);return finish(g);}
async function save(g){const bytes=g.model();for(const[ext,v]of[['onnx',bytes],['json',JSON.stringify(g.json(),null,2)+'\n']]){const filename=`${g.name}.${ext}`,tmp=new URL(`${filename}.pending-${process.pid}`,dir);await writeFile(tmp,v);await rename(tmp,new URL(filename,dir));}return{name:g.name,nodes:g.nodes.length,bytes:bytes.length,sha256:hash(bytes)};}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){const target=await buildDispelTargetGraph(),step=await buildDispelStepGraph(target),report=[];for(const g of[target,step])report.push(await save(g));await writeFile(new URL('dispel-ai-models.json',dir),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));}
